import * as THREE from'three';
import{createRaceModel,RACE_DISTANCE}from'./race-model.js';
import{createRaceSession,createRaceView,fitRaceCamera}from'./race-session.js';
export const RACE_BODY=`<div class="race-layout"><div id="race-court" class="race-court" tabindex="0" role="img" aria-label="도름이와 토끼가 나란히 달리는 두 줄 트랙"><p id="race-count" class="race-count" role="status"></p></div><section class="race-panel"><div class="race-modes" role="group" aria-label="달리기 조작"><button id="race-mode-tap" aria-pressed="true">톡톡 누르기</button><button id="race-mode-hold" aria-pressed="false">길게 누르기</button></div><p id="race-status" role="status"></p><div class="race-progress"><label>도름이 <progress id="race-player" max="100" value="0"></progress></label><label>토끼 <progress id="race-rabbit" max="100" value="0"></progress></label></div><button id="race-stride" class="race-stride" disabled>Space · 톡톡</button><p class="race-help">초당 2~3번이면 충분해요. 너무 빨리 눌러도 더 빨라지지 않아요. 연타가 불편하면 길게 누르기를 골라요.</p><div class="race-actions"><button id="race-start">준비, 시작!</button><button id="race-pause" hidden>잠깐 쉬기</button><button id="race-restart" hidden>다시 달리기</button></div></section></div>`;
export function createRaceController({ui,getView,getActors,stage,isAllowed=()=>true,reduced=false,doc=globalThis.document,win=globalThis.window,sessionFactory=createRaceSession,viewFactory=createRaceView,fitCamera=fitRaceCamera}){
 const camera=new THREE.OrthographicCamera(-7,7,4,-4,.1,100),$=id=>doc.querySelector('#'+id);let live=null,generation=0,mode='tap';
 function listen(n,type,fn){if(n){n.addEventListener(type,fn);live.listeners.push([n,type,fn]);}}
 function clear(){if(!live)return;live.key=false;live.pointer=null;live.model.hold(false);}
 function render(){if(!live)return;const s=live.model.snapshot();$('race-player').value=100*s.playerDistance/RACE_DISTANCE;$('race-rabbit').value=100*s.rabbitDistance/RACE_DISTANCE;$('race-count').textContent=s.paused?'잠깐 쉬어요':s.phase==='countdown'?String(Math.ceil(s.countdown)):s.phase==='running'?'결승선까지 함께!':s.phase==='result'?'도착!':'나란히, 준비';$('race-status').textContent=s.paused?'계속하기를 누르면 이어서 달려요':s.phase==='ready'?'조작을 고른 뒤 시작해요':s.phase==='countdown'?'신호 뒤에 눌러요':s.phase==='result'?s.winner==='tie'?'거의 동시에 도착했어요!':s.winner==='player'?'도름이가 먼저 도착했어요! 함께 한 번 더?':'토끼가 먼저 도착했어요! 편한 박자로 다시 해 봐요':s.rabbitFinish!==null?'토끼가 도착했어요. 도름이도 자기 속도로 끝까지!':'Space 또는 큰 버튼으로 발걸음을 보태요';$('race-stride').textContent=mode==='hold'?'Space · 길게 누르기':'Space · 톡톡';$('race-stride').disabled=s.phase!=='running'||s.paused||s.playerFinish!==null;$('race-start').hidden=s.phase!=='ready';$('race-pause').hidden=['ready','result'].includes(s.phase);$('race-pause').textContent=s.paused?'계속하기':'잠깐 쉬기';$('race-restart').hidden=s.phase!=='result';for(const m of['tap','hold'])$('race-mode-'+m).setAttribute('aria-pressed',String(mode===m));$('race-court').setAttribute('aria-label',$('race-status').textContent);}
 function observe(){if(!live)return;const s=live.model.snapshot();live.session.update(s,reduced);live.view.update(s);render();}
 function pause(){if(!live)return;clear();live.model.pause();observe();}
 function clean(token){if(!live||token!==generation)return;const old=live;clear();live=null;generation++;old.observer?.disconnect();for(const[n,t,fn]of old.listeners)n.removeEventListener(t,fn);try{old.model.dispose();old.view.dispose();}finally{old.session.dispose();stage.classList.remove('race-open');doc.body?.classList.remove('race-open');}}
 function close(){if(!live)return;clean(generation);ui.close();}
 function open(){if(live||!isAllowed())return false;const source=getView();if(!source?.root)return false;const token=++generation;return ui.workshop('토끼와 나란히 달리기',RACE_BODY,()=>{let session,view;try{session=sessionFactory({view:source,...getActors()});view=viewFactory(source.root);live={source,session,view,model:createRaceModel(),listeners:[],key:false,pointer:null,fit:null};stage.classList.add('race-open');doc.body?.classList.add('race-open');const act=(id,fn)=>listen($(id),'click',e=>{if(!live||token!==generation)return;e.preventDefault();fn();});
  const start=()=>{clear();live.model.reset();live.model.start();observe();$('race-court').focus();};act('race-start',start);act('race-restart',start);act('race-pause',()=>{if(doc.hidden)return;if(live.model.snapshot().paused){clear();live.model.resume();observe();$('race-court').focus();}else pause();});
  for(const choice of['tap','hold'])act('race-mode-'+choice,()=>{clear();mode=choice;render();$('race-court').focus();});
  const stride=$('race-stride');listen(stride,'pointerdown',e=>{if(!live||e.button!==0)return;e.preventDefault();if(e.isPrimary===false||live.pointer){clear();return;}live.pointer={id:e.pointerId,x:e.clientX??0,y:e.clientY??0,cancelled:false};stride.setPointerCapture?.(e.pointerId);if(mode==='hold')live.model.hold(true);});listen(stride,'pointermove',e=>{const p=live?.pointer;if(p?.id===e.pointerId&&Math.hypot((e.clientX??p.x)-p.x,(e.clientY??p.y)-p.y)>12){p.cancelled=true;live.model.hold(false);}});for(const type of['pointerup','pointercancel','lostpointercapture'])listen(stride,type,e=>{if(live?.pointer?.id!==e.pointerId)return;const p=live.pointer;live.pointer=null;live.model.hold(false);if(type==='pointerup'&&!p.cancelled&&mode==='tap')live.model.tap();});act('race-stride',()=>{});listen(stride,'click',e=>{if(live&&token===generation&&e.detail===0&&mode==='tap'&&!live.key)live.model.tap();});
  listen(doc,'keydown',e=>{if(!live||!['Space','Enter'].includes(e.code)||e.code==='Enter'&&e.target?.id!=='race-stride'||e.ctrlKey||e.metaKey||e.altKey||['INPUT','SELECT','TEXTAREA'].includes(e.target?.tagName)||e.target?.tagName==='BUTTON'&&e.target.id!=='race-stride')return;e.preventDefault();if(e.repeat||live.key)return;live.key=e.code;if(mode==='hold')live.model.hold(true);else live.model.tap();});listen(doc,'keyup',e=>{if(live&&e.code===live.key){live.key=false;live.model.hold(false);}});listen(win,'blur',pause);listen(doc,'visibilitychange',()=>{if(doc.hidden)pause();});
  const resize=()=>{if(live){live.fit=null;viewport(stage.clientWidth||350,stage.clientHeight||640);}};listen(win,'resize',resize);if(win.visualViewport)listen(win.visualViewport,'resize',resize);if(typeof ResizeObserver==='function'){live.observer=new ResizeObserver(resize);live.observer.observe($('race-court'));}observe();resize();$('race-court').focus();return()=>clean(token);
 }catch{if(live)clean(token);else{view?.dispose();session?.dispose();}ui.close();ui.toast('달리기를 준비하지 못했어요. 다시 열어 주세요');}}, {kind:'race-workshop',closeLabel:'나가기'});}
 function viewport(width,height){if(!live)return{x:0,y:0,width,height};const box=$('race-court').getBoundingClientRect(),base=stage.getBoundingClientRect(),x=Math.max(0,box.left-base.left),y=Math.max(0,box.top-base.top),rect={x,y,width:Math.max(1,Math.min(box.width,width-x)),height:Math.max(1,Math.min(box.height,height-y))};fitCamera(camera,live.source.root,rect,live.model.snapshot());return rect;}
 return{open,close,cancel:close,pause,camera,viewport,tick(dt){if(live){live.model.advance(dt);observe();}},get active(){return!!live;},snapshot:()=>live?.model.snapshot()??null};
}
